SELECT a.final_result, f.decision, f.original_decision, f.final_entry_allowed, COUNT(*) AS n, COUNT(DISTINCT a.reference_signal_id) AS refs FROM crypto_ai.buy_htf_assessment_audit a JOIN crypto_ai.trade_signal f ON f.id = a.five_minute_signal_id WHERE a.replay_mode = 0 AND (f.final_entry_allowed = 0 OR f.original_decision IN ('SELL','STRONG_SELL')) GROUP BY a.final_result, f.decision, f.original_decision, f.final_entry_allowed ORDER BY n DESC LIMIT 40;
SELECT p.id, p.symbol, p.status, p.realized_pnl, p.opened_at, a.final_result, f.id AS five_id, f.decision, f.original_decision, f.final_entry_allowed FROM crypto_ai.paper_position p JOIN crypto_ai.buy_htf_assessment_audit a ON a.reference_signal_id = p.signal_id AND a.replay_mode = 0 JOIN crypto_ai.trade_signal f ON f.id = a.five_minute_signal_id WHERE f.final_entry_allowed = 0 OR f.original_decision IN ('SELL','STRONG_SELL') ORDER BY p.id LIMIT 100;